```c#
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Mail;

namespace SendEmail
{
    class Program
    {
        static void Main(string[] args)
        {
            // Get the list of email addresses to send to.
            List<string> subscribers = new List<string> { "user1@example.com", "user2@example.com", "user3@example.com" };

            // Get the three email accounts to use.
            string[] accounts = { "account1@example.com", "account2@example.com", "account3@example.com" };

            // Create a new MailMessage object.
            MailMessage message = new MailMessage();

            // Set the sender's email address.
            message.From = accounts[0];

            // Set the recipient's email addresses.
            foreach (string subscriber in subscribers)
            {
                message.To.Add(subscriber);
            }

            // Set the subject line.
            message.Subject = "My email subject";

            // Set the body of the email.
            message.Body = "My email body";

            // Send the email.
            SmtpClient client = new SmtpClient("smtp.example.com", 587);
            client.EnableSsl = true;
            client.Credentials = new NetworkCredential(accounts[0], "password");
            client.Send(message);
        }
    }
}
```

To use this application, you will need to replace the following:

