```

Now, create a JavaScript file called `script.js` and include the following code to create a simple 2D car simulation:

```javascript
const { Engine, Render, World, Bodies, Body, Constraint, Mouse, MouseConstraint } = Matter;

const canvas = document.getElementById('game');
const engine = Engine.create();
const render = Render.create({
  canvas: canvas,
  engine: engine,
  options: { wireframes: false },
});

const ground = Bodies.rectangle(400, 600, 810, 60, { isStatic: true });
const car = Bodies.rectangle(400, 500, 100, 50);
const wheel1 = Bodies.circle(350, 525, 25);
const wheel2 = Bodies.circle(450, 525, 25);
const wheelAxle1 = Constraint.create({ bodyA: car, pointA: { x: -50, y: 25 }, bodyB: wheel1, pointB: { x: 0, y: 0 } });
const wheelAxle2 = Constraint.create({ bodyA: car, pointA: { x: 50, y: 25 }, bodyB: wheel2, pointB: { x: 0, y: 0 } });

const ball = Bodies.circle(200, 200, 30);
ball.restitution = 0.9;
ball.frictionAir = 0.01;

World.add(engine.world, [ground, car, wheel1, wheel2, wheelAxle1, wheelAxle2, ball]);
Engine.run(engine);
Render.run(render);

document.addEventListener('keydown', (event) => {
  if (event.key === 'a' || event.key === 'ArrowLeft') {
    Body.setAngularVelocity(wheel1, -0.2);
    Body.setAngularVelocity(wheel2, -0.2);
