function update() {
  // Update ball position
  ball.x += ball.speed;

  // Check for collisions with paddle and edges
  if (ball.x <= paddle.x && ball.y >= paddle.y && ball.y <= paddle.y + paddle.height) {
    // Bounce ball off paddle
