A grow-only counter CRDT (Conflict-free Replicated Data Type) is a distributed counter that supports increments and allows replica divergence while guaranteeing strong eventual consistency.

Here's a simple implementation of a grow-only counter CRDT in TypeScript:

```typescript
// Create an interface for the counter object
interface Counter {
  replicaId: string;
  count: number;
}

// Define the GCounter (Grow-only Counter) class
class GCounter {
  private counters: Map<string, Counter>;

  constructor(replicaId: string) {
    this.counters = new Map<string, Counter>();
    this.counters.set(replicaId, { replicaId, count: 0 });
  }

  // Increment the counter for the current replica
  increment(replicaId: string, value: number = 1): void {
    const counter = this.counters.get(replicaId);
    if (counter) {
      this.counters.set(replicaId, { replicaId, count: counter.count + value });
    }
  }

  // Merge the states of two replicas
  merge(otherCounter: GCounter): void {
    for (let [replicaId, other_counter] of otherCounter.counters.entries()) {
      const local_counter = this.counters.get(replicaId);

      if (!local_counter || other_counter.count > local_counter.count) {
        this.counters.set(replicaId, other_counter);
      }
    }
  }

  // Get the total value of the counter
  getValue(): number {
    let total = 0;
    for (let counter of this.counters.values()) {
      total += counter.count;
    }
    return total;
  }
}

// Usage example
const gCounter1 = new GCounter('replica1');
const gCounter2 = new GCounter('replica2');

gCounter1.increment('replica1', 5);
gCounter2.increment('replica2', 3);

gCounter1.merge(gCounter2);

console.log('Counter 1 value:', gCounter1.getValue()); // Output: Counter 1 value: 8
console.log('Counter 2 value:', gCounter2.getValue()); // Output: Counter 2 value: 3
```

This implementation provides a `GCounter` class which maintains a map of counter objects indexed by a replica ID. Each counter object consists of a replica ID and a count (initialized to 0). The class provides methods for incrementing the counter, merging the state of two replicas, and getting the total value of the counter.

